import {z} from 'zod';

import {isValidTimeZone, MESSENGER_REPLY_TIMES} from './office-hours.js';

/* Visitor ids are generated by the messenger loader and opaque to the server, but bounded so they
cannot stuff arbitrary payloads into the identity table. */
export const VISITOR_ID_PATTERN = /^[A-Za-z0-9_-]{16,64}$/;

export const MESSAGE_BODY_MAX_LENGTH = 5000;

const messageBody = z.string().trim().min(1, 'Message cannot be empty').max(MESSAGE_BODY_MAX_LENGTH);

/* The text sent alongside a file, which may be empty. */
const attachmentCaption = z.object({
  body: z.string().trim().max(MESSAGE_BODY_MAX_LENGTH).optional().default(''),
});

export function normalizeOrigin(value: string): string | null {
  try {
    const url = new URL(value.trim());
    if (url.protocol !== 'https:' && url.protocol !== 'http:') {
      return null;
    }
    return url.origin;
  } catch {
    return null;
  }
}

/* Posting goes server-side to whatever URL is saved, so only Slack's own webhook host is accepted. */
export function isSlackWebhookUrl(value: string): boolean {
  try {
    const url = new URL(value);
    return url.protocol === 'https:' && url.hostname === 'hooks.slack.com' && url.pathname.startsWith('/services/') && !url.port;
  } catch {
    return false;
  }
}

const slackWebhookUrl = z
  .string()
  .trim()
  .max(500)
  .refine(value => value === '' || isSlackWebhookUrl(value), 'Use a Slack incoming webhook URL such as https://hooks.slack.com/services/…')
  .nullable()
  .transform(value => value || null);

const origin = z
  .string()
  .trim()
  .min(1)
  .transform((value, ctx) => {
    const normalized = normalizeOrigin(value);
    if (!normalized) {
      ctx.addIssue({code: z.ZodIssueCode.custom, message: `"${value}" is not a valid origin`});
      return z.NEVER;
    }
    return normalized;
  });

export const MessengerSchemas = {
  boot: z.object({
    visitorId: z.string().regex(VISITOR_ID_PATTERN, 'Invalid visitor id'),
    /* The embedding page's origin as seen by the loader's postMessage; absent when standalone. */
    parentOrigin: z.string().max(300).optional(),
  }),
  startConversation: z.object({
    body: messageBody,
    turnstileToken: z.string().max(4096).optional(),
  }),
  sendMessage: z.object({
    body: messageBody,
  }),
  sendAttachment: attachmentCaption,
  captureEmail: z.object({
    email: z.string().trim().toLowerCase().email('Enter a valid email address').max(254),
    /* Marketing consent is opt-in only: absent means no. */
    subscribe: z.boolean().optional().default(false),
    conversationId: z.string().uuid(),
  }),
} as const;

export const CONVERSATION_VIEWS = ['unassigned', 'mine', 'all', 'closed'] as const;
export type ConversationView = (typeof CONVERSATION_VIEWS)[number];

export const ConversationSchemas = {
  list: z.object({
    view: z.enum(CONVERSATION_VIEWS).default('all'),
    tag: z.string().uuid().optional(),
    cursor: z.string().optional(),
    limit: z
      .union([z.number(), z.string()])
      .transform(value => parseInt(String(value), 10))
      .pipe(z.number().int().min(1).max(100))
      .optional()
      .default(30),
  }),
  reply: z.object({
    body: messageBody,
  }),
  replyAttachment: attachmentCaption,
  status: z.discriminatedUnion('status', [
    z.object({status: z.literal('OPEN')}),
    z.object({status: z.literal('CLOSED')}),
    /* A null date snoozes until the visitor replies. */
    z.object({status: z.literal('SNOOZED'), snoozedUntil: z.coerce.date().nullable()}),
  ]),
  assign: z.object({
    assigneeId: z.string().uuid().nullable(),
  }),
  note: z.object({
    body: messageBody,
    mentionedUserIds: z.array(z.string().uuid()).max(20).optional().default([]),
  }),
  tag: z.object({
    name: z.string().trim().min(1, 'Name the tag').max(40),
  }),
  applyTag: z.object({
    tagId: z.string().uuid(),
  }),
  savedReply: z.object({
    title: z.string().trim().min(1, 'Give the reply a title').max(80),
    body: messageBody,
  }),
  savedReplyUpdate: z.object({
    title: z.string().trim().min(1, 'Give the reply a title').max(80).optional(),
    body: messageBody.optional(),
  }),
} as const;

/* Reserved: emitted by the server only, offered in the workflow trigger picker of projects with the messenger on. */
export const CHAT_EVENTS = {
  STARTED: 'conversation.started',
  REPLIED: 'conversation.replied',
  CLOSED: 'conversation.closed',
  EMAIL_CAPTURED: 'chat.email_captured',
} as const;
export const CHAT_EVENT_NAMES: readonly string[] = Object.values(CHAT_EVENTS);

export const MESSENGER_DEFAULT_ACCENT = '#111827';
export const MESSENGER_GREETING_MAX_LENGTH = 80;
export const MESSENGER_TEAM_MAX = 5;
export const MESSENGER_LAUNCHER_POSITIONS = ['LEFT', 'RIGHT'] as const;
export const MESSENGER_EMAIL_DELAY_DEFAULT_MINUTES = 5;
export const MESSENGER_EMAIL_DELAY_MAX_MINUTES = 1440;
const HOSTNAME = /^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;

export const MessengerSettingsSchemas = {
  update: z.object({
    enabled: z.boolean().optional(),
    allowedOrigins: z.array(origin).max(50).optional(),
    accentColor: z
      .string()
      .regex(/^#[0-9a-fA-F]{6}$/, 'Use a six-digit hex colour such as #111827')
      .transform(value => value.toLowerCase())
      .optional(),
    launcherPosition: z.enum(MESSENGER_LAUNCHER_POSITIONS).optional(),
    greeting: z
      .string()
      .trim()
      .max(MESSENGER_GREETING_MAX_LENGTH)
      .nullable()
      .transform(value => value || null)
      .optional(),
    teamUserIds: z.array(z.string().uuid()).max(MESSENGER_TEAM_MAX).optional(),
    replyDomain: z
      .string()
      .trim()
      .toLowerCase()
      .refine(value => value === '' || HOSTNAME.test(value), 'Use a domain name such as reply.example.com')
      .nullable()
      .transform(value => value || null)
      .optional(),
    replyFromEmail: z
      .string()
      .trim()
      .toLowerCase()
      .refine(value => value === '' || z.string().email().safeParse(value).success, 'Use an email address such as support@example.com')
      .nullable()
      .transform(value => value || null)
      .optional(),
    emailDelayMinutes: z.number().int().min(1).max(MESSENGER_EMAIL_DELAY_MAX_MINUTES).optional(),
    slackWebhookUrl: slackWebhookUrl.optional(),
    replyTime: z.enum(MESSENGER_REPLY_TIMES).optional(),
    officeHoursEnabled: z.boolean().optional(),
    officeHours: z
      .array(
        z
          .object({
            day: z.number().int().min(1).max(7),
            start: z.number().int().min(0).max(1439),
            end: z.number().int().min(1).max(1440),
          })
          .refine(day => day.end > day.start, 'Closing time must be after opening time'),
      )
      .max(7)
      .refine(days => new Set(days.map(day => day.day)).size === days.length, 'Each weekday can only appear once')
      .optional(),
    timezone: z.string().trim().max(64).refine(isValidTimeZone, 'Choose a time zone from the list').optional(),
  }),
  slackTest: z.object({
    url: slackWebhookUrl.optional(),
  }),
} as const;

export const ProfileSchemas = {
  update: z.object({
    name: z
      .string()
      .trim()
      .max(60)
      .nullable()
      .transform(value => value || null),
  }),
} as const;

export const NotificationSchemas = {
  prefs: z
    .object({
      inboxBadge: z.boolean(),
      inboxTitleCount: z.boolean(),
      inboxSound: z.boolean(),
      pushPreview: z.boolean(),
      inboxEmail: z.boolean(),
    })
    .partial(),
  subscribe: z.object({
    endpoint: z.string().url().max(2048).startsWith('https://'),
    keys: z.object({
      p256dh: z.string().min(1).max(256),
      auth: z.string().min(1).max(256),
    }),
  }),
  unsubscribe: z.object({
    endpoint: z.string().max(2048),
  }),
} as const;
